    //     newDir = next > last ? 1 : 0
    //     newH = h, newV = v
    //     // Check if position i is a peak or valley
    //     // Position i is a peak if dir (from i-1 to i) is up (1) and newDir (from i to i+1) is down (0)
    //     // Position i is a valley if dir is down (0) and newDir is up (1)
    //     if (dir === 1 && newDir === 0) {
    //         newH = h + 1;
    //     } else if (dir === 0 && newDir === 1) {
    //         newV = v + 1;
    //     }
    //     dp[i+1][next][newH][newV][newDir] += dp[i][last][h][v][dir]
    //
    // At the end (i=n), we need to check if the last position n-1 could be a peak or valley.
    // Wait, peaks and valleys are only counted for positions 2 to n-1.
    // In our transition, when we go from i to i+1, we check position i.
    // So when i goes from 2 to n-1, we check positions 2 to n-1.
    // The last transition is from i=n-1 to i=n, which checks position n-1.
    // So all positions 2 to n-1 are checked.
    //
    // Final answer: sum of dp[n][last][t][t-1][dir] for all last and dir.

    const MAX_Y = 4;
    const MAX_N = 20;
    const MAX_T = 10;

