    // dir: 0 or 1

    // Initialize dp as a 5D array or use nested objects/arrays.
    // Since n <= 20, t <= 10, we can use a 5D array.
    // dp[i][j][h][v][d]

    const dp = new Array(n + 1).fill(null).map(() =>
        new Array(MAX_Y + 1).fill(null).map(() =>
            new Array(t + 1).fill(null).map(() =>
