    for (let i = 2; i < n; i++) {
        for (let last = 1; last <= MAX_Y; last++) {
            for (let h = 0; h <= t; h++) {
                for (let v = 0; v <= t; v++) {
                    for (let dir = 0; dir <= 1; dir++) {
                        const count = dp[i][last][h][v][dir];
