                        for (let next = 1; next <= MAX_Y; next++) {
                            if (next === last) continue;
                            const newDir = next > last ? 1 : 0;
                            let newH = h;
                            let newV = v;
                            if (dir === 1 && newDir === 0) {
                                newH = h + 1;
                            } else if (dir === 0 && newDir === 1) {
