function countCamels(n, t) {
    // dp[i][j][k][last] = number of ways to have i vertices, j humps, k valleys, ending with value 'last'
    // But we need to track the direction to determine humps/valleys
    // Actually, let's use: dp[i][humps][valleys][lastY][prevDirection]
    // Where prevDirection is 1 if last step was up, -1 if down
    // But we can also just track the last two y values to determine the turn

    // Let's use: dp[i][humps][valleys][lastY] but we need to know the previous direction
    // Alternative: dp[i][humps][valleys][lastY][prevY] is too large
    // Better: dp[i][humps][valleys][lastY][dir] where dir = 1 (up) or -1 (down)

    const maxHumps = t;
    const maxValleys = t - 1;

    // dp[i][h][v][y][d] where d is 0 for up, 1 for down
    // i from 1 to n
    // h from 0 to maxHumps
    // v from 0 to maxValleys
    // y from 1 to 4
    // d from 0 to 1

    // Initialize: for i=1, we have just one point, no direction yet
    // For i=2, we have a direction

    // Let's use a 5D array or nested objects
    // dp[i][h][v][y][d]

    const dp = new Array(n + 1);
    for (let i = 0; i <= n; i++) {
        dp[i] = new Array(maxHumps + 1);
        for (let h = 0; h <= maxHumps; h++) {
            dp[i][h] = new Array(maxValleys + 1);
            for (let v = 0; v <= maxValleys; v++) {
                dp[i][h][v] = new Array(5); // y from 1 to 4
                for (let y = 1; y <= 4; y++) {
                    dp[i][h][v][y] = new Array(2); // d: 0=up, 1=down
                    dp[i][h][v][y][0] = 0;
                    dp[i][h][v][y][1] = 0;
                }
            }
        }
    }

    // Base case: i=1, no direction
    // We'll handle i=2 as the first step

    // For i=1, we can't define direction, so let's start from i=2
    // Actually, let's think differently.
    // At step i (i>=2), we have a direction.
    // For i=1, we just have a y value.

    // Let's redefine: 
    // dp[i][h][v][y] = number of ways to reach vertex i with y-coordinate y, having h humps and v valleys so far
    // But to determine if adding a new point creates a hump or valley, we need the previous direction.
    // So we need to track the direction.

    // Let's use: dp[i][h][v][y][d] where d indicates the direction of the segment from i-1 to i
    // For i=1, there's no previous segment, so we can initialize separately.

    // Initialize for i=1:
    // We'll say for i=1, we don't have a direction. Let's handle i=2 as the transition.

    // Alternative approach:
    // dp[i][h][v][y][d] for i >= 2
    // For i=1, we just have y, and we'll transition to i=2.

    // Let's initialize dp[1][0][0][y][?] - but d is not defined for i=1.
    // So let's start counting from i=2.

    // For i=2:
    // For each y1 in 1..4, y2 in 1..4, y1 != y2
    // h=0, v=0
    // d = (y2 > y1) ? 0 : 1

    for (let y1 = 1; y1 <= 4; y1++) {
        for (let y2 = 1; y2 <= 4; y2++) {
            if (y1 === y2) continue;
            const d = (y2 > y1) ? 0 : 1; // 0=up, 1=down
            dp[2][0][0][y2][d] += 1;
        }
    }

    // Transition for i from 3 to n:
    for (let i = 3; i <= n; i++) {
        for (let h = 0; h <= maxHumps; h++) {
            for (let v = 0; v <= maxValleys; v++) {
                for (let prevY = 1; prevY <= 4; prevY++) {
                    for (let prevD = 0; prevD <= 1; prevD++) {
                        const count = dp[i-1][h][v][prevY][prevD];
                        if (count === 0) continue;

                        for (let newY = 1; newY <= 4; newY++) {
                            if (newY === prevY) continue;

                            const newD = (newY > prevY) ? 0 : 1; // 0=up, 1=down

                            let newH = h;
                            let newV = v;

                            // Check if this creates a hump or valley
                            // A hump: prevD was up (0), newD is down (1), and prevY is the peak
                            // Actually: hump at position i-1 if y[i-2] < y[i-1] > y[i]
                            // So if prevD was up (meaning y[i-2] < y[i-1]) and newD is down (meaning y[i-1] > y[i])
                            // Then we have a hump at i-1

                            // A valley: prevD was down (1), newD is up (0)
                            // Then we have a valley at i-1

                            if (prevD === 0 && newD === 1) {
                                // Was going up, now going down -> hump at i-1
                                newH = h + 1;
                            } else if (prevD === 1 && newD === 0) {
                                // Was going down, now going up -> valley at i-1
                                newV = v + 1;
                            }
                            // If same direction, no new hump or valley

                            if (newH <= maxHumps && newV <= maxValleys) {
                                dp[i][newH][newV][newY][newD] += count;
                            }
                        }
                    }
                }
            }
        }
    }

    // Sum up all dp[n][t][t-1][y][d] for all y and d
    let result = 0;
    for (let y = 1; y <= 4; y++) {
        for (let d = 0; d <= 1; d++) {
            result += dp[n][t][t-1][y][d];
        }
    }

    return result;
}
