    // i from 2 to n
    // a, b from 1 to 4
    // h from 0 to t
    // v from 0 to t-1

    // Use a 5D array or nested objects. Given small constraints, let's use a 5D array.
    // dp[i][a][b][h][v]

    const dp = new Array(n + 1);
    for (let i = 0; i <= n; i++) {
        dp[i] = new Array(maxY + 1);
