                        for (let c = 1; c <= maxY; c++) {
                            if (b === c) continue;

                            let newH = h;
                            let newV = v;

                            // Check if b (at position i-1) is a hump or valley
                            if (a < b && b > c) {
                                newH++;
                            } else if (a > b && b < c) {
                                newV++;
                            }

                            if (newH <= t && newV <= t - 1) {
                                dp[i][b][c][newH][newV] += count;
                            }
                        }
                    }
                }
            }
        }
