    // where c is y[i+1], c != b.
    // Now we can check if index i (which has value b) is a hump or valley.
    // We have y[i-1]=a, y[i]=b, y[i+1]=c.
    // If a < b > c, then b is a hump: h' = h + 1, v' = v
    // If a > b < c, then b is a valley: h' = h, v' = v + 1
    // Otherwise: h' = h, v' = v

    // At the end, we need dp[n][a][b][t][t-1] for all a,b.

    const maxVal = 4;
    const maxHumps = t;
    const maxValleys = t - 1;

    // dp[i][a][b][h][v]
    // i from 2 to n
    // a, b from 1 to 4
    // h from 0 to maxHumps
    // v from 0 to maxValleys

    // Initialize dp for i=2
