        const newDp = {};
        for (let a = 1; a <= maxVal; a++) {
            for (let b = 1; b <= maxVal; b++) {
                for (let h = 0; h <= maxHumps; h++) {
                    for (let v = 0; v <= maxValleys; v++) {
                        const k = key(i, a, b, h, v);
                        const count = dp[k];
                        if (count === undefined) continue;

                        for (let c = 1; c <= maxVal; c++) {
                            if (c === b) continue;

                            let newH = h;
                            let newV = v;

                            // Check if index i (value b) is a hump or valley
                            // y[i-1]=a, y[i]=b, y[i+1]=c
                            if (a < b && b > c) {
                                newH = h + 1;
                            } else if (a > b && b < c) {
                                newV = v + 1;
                            }

                            if (newH <= maxHumps && newV <= maxValleys) {
                                const nk = key(i + 1, b, c, newH, newV);
                                newDp[nk] = (newDp[nk] || 0) + count;
                            }
                        }
                    }
                }
            }
        }

        // Merge newDp into dp (or just replace)
        // Actually, we can just use newDp as the next state
        // But we need to keep only the current i's states
        // Let's clear dp and set to newDp
        for (const k in dp) {
            delete dp[k];
        }
        for (const k in newDp) {
            dp[k] = newDp[k];
        }
    }

    // Sum up all dp[n][a][b][t][t-1]
    let result = 0;
    for (let a = 1; a <= maxVal; a++) {
        for (let b = 1; b <= maxVal; b++) {
            const k = key(n, a, b, t, t - 1);
            if (dp[k] !== undefined) {
                result += dp[k];
            }
        }
    }

    console.log(result);
});
