                                // curr is a valley
                                newK = k + 1;
                            }

                            // Check bounds
                            if (newJ > maxT || newK > maxT) continue;

                            // Also, we need to ensure that the number of valleys is exactly t-1 at the end.
                            // But during DP, we just track counts.

                            dp[i + 1][newJ][newK][curr][next] += dp[i][j][k][prev][curr];
                        }
                    }
                }
            }
        }
    }

    // Sum up all valid states at i=n
    // We need exactly t peaks and t-1 valleys
    let result = 0;
    for (let prev = 1; prev <= maxY; prev++) {
        for (let curr = 1; curr <= maxY; curr++) {
            result += dp[n][t][t - 1][prev][curr];
        }
    }

    console.log(result);
