    // For i>=2:
    //   dp[i][yi][yprev][maxCount][minCount] = sum over yprev2 in 0..3, yprev2 != yprev
    //     of dp[i-1][yprev][yprev2][maxCount'][minCount']
    //     where maxCount' = maxCount - (isLocalMax ? 1 : 0)
    //     and minCount' = minCount - (isLocalMin ? 1 : 0)
    //     isLocalMax = (yprev2 < yprev && yprev > yi)
    //     isLocalMin = (yprev2 > yprev && yprev < yi)

    // Let's implement this.

    const dp = new Array(n);
    for (let i = 0; i < n; i++) {
        dp[i] = new Array(4);
        for (let yi = 0; yi < 4; yi++) {
            dp[i][yi] = new Array(4);
            for (let yprev = 0; yprev < 4; yprev++) {
                dp[i][yi][yprev] = new Array(t + 1);
