                }
            }
        }
    }

    // Initialize i=0
    for (let yi = 0; yi < 4; yi++) {
        dp[0][yi][0][0][0] = 1; // yprev=0 is a dummy
    }

    // Initialize i=1
    for (let yi = 0; yi < 4; yi++) {
        for (let yprev = 0; yprev < 4; yprev++) {
            if (yi === yprev) continue;
            dp[1][yi][yprev][0][0] = 1;
        }
    }

    // Fill for i>=2
    for (let i = 2; i < n; i++) {
        for (let yi = 0; yi < 4; yi++) {
            for (let yprev = 0; yprev < 4; yprev++) {
                if (yi === yprev) continue;
                for (let maxCount = 0; maxCount <= t; maxCount++) {
