```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

let input = '';
rl.on('line', (line) => {
    input += line + '\n';
});

rl.on('close', () => {
    const parts = input.trim().split(/\s+/);
    const n = parseInt(parts[0]);
    const t = parseInt(parts[1]);

    // We need to count sequences y1, y2, ..., yn where:
    // 1. Each yi is in {1, 2, 3, 4}
    // 2. No two consecutive yi are equal (no segment parallel to Ox-axis)
    // 3. Exactly t peaks: indices j (2<=j<=n-1) where y[j-1] < y[j] > y[j+1]
    // 4. Exactly t-1 valleys: indices j (2<=j<=n-1) where y[j-1] > y[j] < y[j+1]

    // Note: Since no two consecutive are equal, for each internal index j (2 to n-1),
    // either y[j-1] < y[j] > y[j+1] (peak), or y[j-1] > y[j] < y[j+1] (valley),
    // or it's monotonic (y[j-1] < y[j] < y[j+1] or y[j-1] > y[j] > y[j+1]).
    // Wait, the problem says "there should be t humps precisely" and "precisely t-1 such indexes ... valleys".
    // The conditions are:
    // - Count of j in [2, n-1] with y[j-1] < y[j] > y[j+1] is exactly t.
    // - Count of j in [2, n-1] with y[j-1] > y[j] < y[j+1] is exactly t-1.

    // We can use dynamic programming.
    // State: (position, last_value, current_peaks, current_valleys, last_direction)
    // But we need to know the previous two values to determine if the current position is a peak or valley.
    // Actually, when we are at position i, we have chosen y[1]...y[i].
    // To determine if position i-1 is a peak or valley, we need y[i-2], y[i-1], y[i].
    // So the state should include the last two values.

    // Let dp[i][a][b][p][v] = number of ways to have a sequence of length i,
    // where y[i-1] = a, y[i] = b, with p peaks and v valleys so far (considering indices 2 to i-1).
    // Wait, peaks and valleys are determined at internal indices.
    // When we add a new element y[i], we can determine if index i-1 is a peak or valley based on y[i-2], y[i-1], y[i].
    // So when transitioning from state (i-1, a, b) to (i, b, c), we check if index i-1 (which has value b) is a peak or valley.
    // Index i-1 is a peak if a < b > c.
    // Index i-1 is a valley if a > b < c.

    // Base case: i=2. We have y[1]=a, y[2]=b. No internal indices yet (indices 2 to n-1, so for n=2 there are none, but n>=3).
    // For i=2, we have no peaks or valleys determined yet because the first internal index is 2, which requires y[1], y[2], y[3].
    // So for i=2, p=0, v=0.

    // Transition: from state (i-1, a, b) with p peaks and v valleys, we choose c (y[i]) such that c != b.
    // Then we check index i-1 (value b):
    //   if a < b > c: new_p = p + 1, new_v = v
    //   if a > b < c: new_p = p, new_v = v + 1
    //   else: new_p = p, new_v = v
    // New state: (i, b, c, new_p, new_v)

    // We want the answer to be the sum of dp[n][a][b][t][t-1] for all valid a, b.

    // Constraints: n <= 20, t <= 10.
    // a, b, c in {1,2,3,4}.
    // p can be up to t (10), v up to t-1 (9).
    // So dp[i][a][b][p][v] where i up to 20, a,b in 1..4, p in 0..10, v in 0..9.
    // This is small enough.

    const maxP = t;
    const maxV = t - 1;

    // dp[i][a][b][p][v]
    // i from 2 to n
    // a, b from 1 to 4
    // p from 0 to maxP
    // v from 0 to maxV

    // Initialize dp for i=2
    // dp[2][a][b][0][0] = 1 for all a != b

    // Use a 5D array or nested objects. Let's use a 5D array.
    // dp[i][a][b][p][v]
    // i: 2..n
    // a: 1..4
    // b: 1..4
    // p: 0..maxP
    // v: 0..maxV

    // We'll use a 4D array for the current i, and update to next i.
    // Actually, let's just use a 5D array for simplicity, or iterate i from 2 to n.

    // Let's create a function to get/set dp values.
    // dp[i][a][b][p][v]

    // Initialize all to 0
    const dp = new Array(n + 1);
    for (let i = 0; i <= n; i++) {
        dp[i] = new Array(5); // index 1..4
        for (let a = 0; a < 5; a++) {
            dp[i][a] = new Array(5);
            for (let b = 0; b < 5; b++) {
                dp[i][a][b] = new Array(maxP + 1);
                for (let p = 0; p <= maxP; p++) {
                    dp[i][a][b][p] = new Array(maxV + 1);
                    for (let v = 0; v <= maxV; v++) {
                        dp[i][a][b][p][v] = 0;
                    }
                }
            }
        }
    }

    // Base case: i=2
    for (let a = 1; a <= 4; a++) {
        for (let b = 1; b <= 4; b++) {
            if (a !== b) {
                dp[2][a][b][0][0] = 1;
            }
        }
    }

    // Transition: for i from 3 to n
    for (let i = 3; i <= n; i++) {
        for (let a = 1; a <= 4; a++) {
            for (let b = 1; b <= 4; b++) {
                for (let p = 0; p <= maxP; p++) {
                    for (let v = 0; v <= maxV; v++) {
                        const count = dp[i-1][a][b][p][v];
                        if (count === 0) continue;

                        for (let c = 1; c <= 4; c++) {
                            if (c === b) continue; // no segment parallel to Ox-axis

                            let newP = p;
                            let newV = v;

                            // Check if index i-1 (value b) is a peak or valley
                            // We have y[i-2]=a, y[i-1]=b, y[i]=c
                            if (a < b && b > c) {
                                // peak
                                newP = p + 1;
                                newV = v;
                            } else if (a > b && b < c) {
                                // valley
                                newP = p;
                                newV = v + 1;
                            } else {
                                // monotonic or other
                                newP = p;
                                newV = v;
                            }

                            if (newP <= maxP && newV <= maxV) {
                                dp[i][b][c][newP][newV] += count;
                            }
                        }
                    }
                }
            }
        }
    }

    // Answer: sum of dp[n][a][b][t][t-1] for all a, b
    let result = 0;
    for (let a = 1; a <= 4; a++) {
        for (let b = 1; b <= 4; b++) {
            if (t <= maxP && t - 1 <= maxV) {
                result += dp[n][a][b][t][t - 1];
            }
        }
    }

    console.log(result);
});
